package in.ac.rtu.medicare.service;
import in.ac.rtu.medicare.dao.UserDao; import in.ac.rtu.medicare.model.User; import in.ac.rtu.medicare.util.*; import java.sql.SQLException;
public class AuthService { private final UserDao users=new UserDao(); public User login(String email,char[] password)throws SQLException {User u=users.findByEmail(Validation.email(email)).orElseThrow(()->new IllegalArgumentException("Invalid email or password"));if(!u.active()||!PasswordHasher.verify(password,u.passwordHash()))throw new IllegalArgumentException("Invalid email or password");return u;} public long register(String n,String e,char[] p,String phone)throws SQLException {n=Validation.required(n,"Name");if(p==null||p.length<8)throw new IllegalArgumentException("Password must have at least 8 characters");return users.createPatient(n,Validation.email(e),PasswordHasher.hash(p),phone);} }
